head.b:skin:
/* ==========================================================================
   AI Tool Scout — design system
   Dark, modern, fast. No framework, fonts self-hosted.
   ========================================================================== */

:root {
  --bg: #070b14;
  --bg-elev: #0c1220;
  --bg-elev-2: #111a2c;
  --surface: #131d33;
  --border: #1e2b47;
  --border-soft: #17233a;

  --text: #e8edf7;
  --text-muted: #9aa8c4;
  --text-dim: #6f7d99;

  --brand: #4f8cff;
  --brand-2: #22d3ee;
  --brand-3: #a78bfa;
  --accent-gradient: linear-gradient(135deg, #4f8cff 0%, #22d3ee 55%, #a78bfa 100%);

  --success: #34d399;
  --warning: #fbbf24;
  --danger: #f87171;

  --radius-sm: 8px;
  --radius: 14px;
  --radius-lg: 22px;

  --shadow-sm: 0 1px 2px rgba(0, 0, 0, .4);
  --shadow: 0 10px 30px -12px rgba(0, 0, 0, .7);
  --shadow-glow: 0 0 0 1px rgba(79, 140, 255, .18), 0 18px 50px -20px rgba(79, 140, 255, .45);

  --container: 1180px;
  --header-h: 66px;

  --font: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
          "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
}

/* ---------- Reset ---------- */
*, *::before, *::after { box-sizing: border-box; }

html {
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
  scroll-padding-top: calc(var(--header-h) + 16px);
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 17px;
  line-height: 1.7;
  font-feature-settings: "cv02", "cv03", "cv04", "cv11";
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(900px 500px at 12% -8%, rgba(79, 140, 255, .16), transparent 60%),
    radial-gradient(760px 460px at 92% 4%, rgba(167, 139, 250, .13), transparent 62%),
    radial-gradient(700px 500px at 50% 110%, rgba(34, 211, 238, .08), transparent 60%);
  pointer-events: none;
}

img, svg, video { max-width: 100%; height: auto; display: block; }

a { color: var(--brand); text-decoration: none; }
a:hover { color: var(--brand-2); }

/* Accessibility — axe/Lighthouse `link-in-text-block`: a link inside running
   text must not rely on colour alone, it has to be underlined too. Scoped to
   .site-main so the header nav, breadcrumb and footer keep their clean
   underline-free look (they are links-as-controls, not links in a sentence). */
.site-main p a,
.site-main blockquote a,
.site-main figcaption a,
.site-main dd a {
  text-decoration: underline;
  text-underline-offset: 3px;
  text-decoration-color: rgba(79, 140, 255, .55);
}
.site-main p a:hover,
.site-main blockquote a:hover,
.site-main figcaption a:hover,
.site-main dd a:hover {
  text-decoration-color: var(--brand-2);
}

h1, h2, h3, h4, h5 {
  margin: 0 0 .5em;
  line-height: 1.22;
  font-weight: 700;
  letter-spacing: -.02em;
  color: #fff;
}
h1 { font-size: clamp(2.1rem, 1.3rem + 3vw, 3.5rem); }
h2 { font-size: clamp(1.6rem, 1.2rem + 1.7vw, 2.35rem); }
h3 { font-size: clamp(1.25rem, 1.05rem + .9vw, 1.6rem); }
h4 { font-size: 1.15rem; }

p { margin: 0 0 1.15em; }

ul, ol { padding-left: 1.3em; }
li { margin-bottom: .45em; }

code, pre, kbd {
  font-family: var(--mono);
  font-size: .9em;
}

hr {
  border: 0;
  height: 1px;
  background: var(--border);
  margin: 2.5rem 0;
}

::selection { background: rgba(79, 140, 255, .35); color: #fff; }

:focus-visible {
  outline: 2px solid var(--brand-2);
  outline-offset: 3px;
  border-radius: 4px;
}

/* ---------- Layout ---------- */
.container {
  width: 100%;
  max-width: var(--container);
  margin-inline: auto;
  padding-inline: 22px;
}

.narrow { max-width: 820px; }

.section { padding: clamp(48px, 7vw, 92px) 0; }
.section-tight { padding: clamp(34px, 5vw, 58px) 0; }

.section-head {
  max-width: 760px;
  margin-bottom: clamp(28px, 4vw, 46px);
}
.section-head.center { margin-inline: auto; text-align: center; }
.section-head p {
  color: var(--text-muted);
  font-size: 1.06rem;
  margin-bottom: 0;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: .78rem;
  font-weight: 700;
  letter-spacing: .13em;
  text-transform: uppercase;
  color: var(--brand-2);
  margin-bottom: 14px;
}
.eyebrow::before {
  content: "";
  width: 22px;
  height: 2px;
  background: var(--accent-gradient);
  border-radius: 2px;
}

.muted { color: var(--text-dim); }
.lead {
  font-size: clamp(1.05rem, 1rem + .4vw, 1.25rem);
  color: var(--text-muted);
  line-height: 1.65;
}

/* ---------- Skip link ---------- */
.skip-link {
  position: absolute;
  left: 12px;
  top: -60px;
  z-index: 200;
  background: var(--brand);
  color: #fff;
  padding: 10px 18px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  transition: top .18s ease;
}
.skip-link:focus { top: 12px; color: #fff; }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 13px 24px;
  border-radius: 999px;
  font-size: .97rem;
  font-weight: 600;
  letter-spacing: -.01em;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform .16s ease, box-shadow .2s ease, background .2s ease,
              border-color .2s ease, color .2s ease;
  white-space: nowrap;
}
.btn:active { transform: translateY(1px); }

.btn-primary {
  background: var(--accent-gradient);
  color: #04070f;
  font-weight: 700;
  box-shadow: var(--shadow-glow);
}
.btn-primary:hover {
  color: #04070f;
  transform: translateY(-2px);
  box-shadow: 0 0 0 1px rgba(79,140,255,.3), 0 22px 44px -18px rgba(79,140,255,.6);
}

.btn-ghost {
  background: rgba(255, 255, 255, .04);
  border-color: var(--border);
  color: var(--text);
}
.btn-ghost:hover {
  background: rgba(255, 255, 255, .08);
  border-color: var(--brand);
  color: #fff;
}

.btn-sm { padding: 9px 18px; font-size: .9rem; }
.btn-lg { padding: 16px 32px; font-size: 1.05rem; }

.btn-group { display: flex; flex-wrap: wrap; gap: 14px; }

/* ---------- Header ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--header-h);
  display: flex;
  align-items: center;
  background: rgba(7, 11, 20, .72);
  backdrop-filter: saturate(180%) blur(14px);
  -webkit-backdrop-filter: saturate(180%) blur(14px);
  border-bottom: 1px solid transparent;
  transition: border-color .25s ease, background .25s ease;
}
.site-header.scrolled {
  background: rgba(7, 11, 20, .92);
  border-bottom-color: var(--border-soft);
}

.header-inner {
  display: flex;
  align-items: center;
  gap: 22px;
  width: 100%;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  font-size: 1.06rem;
  letter-spacing: -.03em;
  color: #fff;
  flex-shrink: 0;
}
.brand:hover { color: #fff; }
.brand-mark {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  background: var(--accent-gradient);
  color: #04070f;
  box-shadow: 0 6px 18px -8px rgba(79, 140, 255, .8);
}
.brand-text { white-space: nowrap; }

.primary-nav { margin-left: auto; }
.primary-nav ul {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
  margin: 0;
  padding: 0;
}
.primary-nav a {
  display: block;
  padding: 8px 14px;
  border-radius: 999px;
  color: var(--text-muted);
  font-size: .95rem;
  font-weight: 500;
  transition: color .18s ease, background .18s ease;
}
.primary-nav a:hover { color: #fff; background: rgba(255, 255, 255, .06); }
.primary-nav a[aria-current="page"] {
  color: #fff;
  background: rgba(79, 140, 255, .16);
}

.header-actions { display: flex; align-items: center; gap: 12px; }

.nav-toggle {
  display: none;
  width: 42px;
  height: 42px;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: 11px;
  background: rgba(255, 255, 255, .04);
  cursor: pointer;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
}
.nav-toggle span {
  display: block;
  width: 17px;
  height: 2px;
  border-radius: 2px;
  background: var(--text);
  transition: transform .22s ease, opacity .18s ease;
}
.nav-toggle[aria-expanded="true"] span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.nav-toggle[aria-expanded="true"] span:nth-child(2) { opacity: 0; }
.nav-toggle[aria-expanded="true"] span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* ---------- Hero ---------- */
.hero {
  position: relative;
  padding: clamp(52px, 8vw, 112px) 0 clamp(40px, 6vw, 76px);
  overflow: hidden;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.06fr .94fr;
  gap: clamp(30px, 5vw, 62px);
  align-items: center;
}
.hero h1 { margin-bottom: 20px; }
.hero h1 .grad {
  background: var(--accent-gradient);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.hero .lead { margin-bottom: 30px; max-width: 560px; }

.hero-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 26px;
}
.pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 14px;
  border-radius: 999px;
  background: rgba(255, 255, 255, .045);
  border: 1px solid var(--border);
  font-size: .83rem;
  color: var(--text-muted);
  font-weight: 500;
}
.pill .dot {
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--success);
  box-shadow: 0 0 0 3px rgba(52, 211, 153, .18);
}

.hero-stats {
  display: flex;
  flex-wrap: wrap;
  gap: clamp(20px, 4vw, 46px);
  margin-top: 40px;
  padding-top: 30px;
  border-top: 1px solid var(--border-soft);
}
.hero-stats .stat strong {
  display: block;
  font-size: clamp(1.5rem, 1.2rem + 1.2vw, 2.1rem);
  font-weight: 800;
  letter-spacing: -.03em;
  background: var(--accent-gradient);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.hero-stats .stat span {
  font-size: .87rem;
  color: var(--text-dim);
}

/* Hero visual card */
.hero-card {
  position: relative;
  background: linear-gradient(160deg, var(--bg-elev-2), var(--bg-elev));
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 22px;
  box-shadow: var(--shadow);
}
.hero-card::before {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(140deg, rgba(79,140,255,.5), transparent 40%, rgba(167,139,250,.4));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}
.hero-card-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-bottom: 14px;
  margin-bottom: 16px;
  border-bottom: 1px solid var(--border-soft);
}
.hero-card-head i {
  width: 10px; height: 10px; border-radius: 50%; background: var(--border);
}
.hero-card-head i:nth-child(1) { background: #ff5f57; }
.hero-card-head i:nth-child(2) { background: #febc2e; }
.hero-card-head i:nth-child(3) { background: #28c840; }
.hero-card-head span {
  margin-left: auto;
  font-size: .78rem;
  color: var(--text-dim);
  font-family: var(--mono);
}

.mini-tool {
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 13px;
  border-radius: var(--radius);
  background: rgba(255, 255, 255, .03);
  border: 1px solid var(--border-soft);
  margin-bottom: 10px;
  transition: border-color .2s ease, transform .2s ease, background .2s ease;
}
.mini-tool:hover {
  border-color: rgba(79, 140, 255, .45);
  background: rgba(79, 140, 255, .07);
  transform: translateX(3px);
}
.mini-tool .ico {
  width: 40px; height: 40px;
  flex-shrink: 0;
  display: grid; place-items: center;
  border-radius: 11px;
  font-weight: 800;
  font-size: .95rem;
  color: #04070f;
}
.mini-tool .meta { flex: 1; min-width: 0; }
.mini-tool .meta strong { display: block; font-size: .96rem; color: #fff; }
.mini-tool .meta span { font-size: .8rem; color: var(--text-dim); }
.mini-tool .score {
  font-weight: 800;
  font-size: .92rem;
  color: var(--success);
  font-family: var(--mono);
}
.bar {
  height: 5px;
  border-radius: 99px;
  background: rgba(255, 255, 255, .07);
  overflow: hidden;
  margin-top: 7px;
}
.bar > i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--accent-gradient);
}

/* ---------- Cards / grids ---------- */
.grid { display: grid; gap: 22px; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }

.card {
  position: relative;
  background: linear-gradient(165deg, rgba(255,255,255,.035), rgba(255,255,255,.012));
  border: 1px solid var(--border-soft);
  border-radius: var(--radius);
  padding: 26px;
  transition: transform .22s ease, border-color .22s ease, box-shadow .22s ease;
}
.card:hover {
  transform: translateY(-4px);
  border-color: rgba(79, 140, 255, .4);
  box-shadow: var(--shadow);
}
.card h3 { margin-bottom: 10px; font-size: 1.16rem; }
.card p { color: var(--text-muted); font-size: .96rem; margin-bottom: 0; }

.card-icon {
  width: 46px; height: 46px;
  display: grid; place-items: center;
  border-radius: 13px;
  background: rgba(79, 140, 255, .14);
  color: var(--brand);
  margin-bottom: 16px;
  font-size: 1.25rem;
}

.card-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 14px;
  font-weight: 600;
  font-size: .93rem;
}
.card-link::after { content: "→"; transition: transform .2s ease; }
.card-link:hover::after { transform: translateX(4px); }

/* ---------- Feature list ---------- */
.check-list { list-style: none; padding: 0; margin: 0; }
.check-list li {
  position: relative;
  padding-left: 30px;
  margin-bottom: 12px;
  color: var(--text-muted);
}
.check-list li::before {
  content: "✓";
  position: absolute;
  left: 0; top: 0;
  width: 20px; height: 20px;
  border-radius: 6px;
  background: rgba(52, 211, 153, .16);
  color: var(--success);
  font-size: .74rem;
  font-weight: 800;
  display: grid;
  place-items: center;
}

/* ---------- CTA band ---------- */
.cta-band {
  position: relative;
  border-radius: var(--radius-lg);
  padding: clamp(34px, 5vw, 60px);
  background:
    linear-gradient(135deg, rgba(79,140,255,.18), rgba(167,139,250,.12) 55%, rgba(34,211,238,.14));
  border: 1px solid rgba(79, 140, 255, .3);
  overflow: hidden;
  text-align: center;
}
.cta-band h2 { margin-bottom: 12px; }
.cta-band p { color: var(--text-muted); max-width: 620px; margin: 0 auto 26px; }
.cta-band .btn-group { justify-content: center; }

/* ---------- Blog ---------- */
.post-card {
  display: flex;
  flex-direction: column;
  background: linear-gradient(165deg, rgba(255,255,255,.035), rgba(255,255,255,.012));
  border: 1px solid var(--border-soft);
  border-radius: var(--radius);
  overflow: hidden;
  transition: transform .22s ease, border-color .22s ease, box-shadow .22s ease;
}
.post-card:hover {
  transform: translateY(-5px);
  border-color: rgba(79, 140, 255, .42);
  box-shadow: var(--shadow);
}
.post-thumb {
  aspect-ratio: 16 / 9;
  display: grid;
  place-items: center;
  position: relative;
  font-size: 2.4rem;
  font-weight: 800;
  color: rgba(255, 255, 255, .92);
  letter-spacing: -.04em;
  overflow: hidden;
}
.post-thumb::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 45%, rgba(7,11,20,.55));
}
.post-body { padding: 20px 22px 24px; display: flex; flex-direction: column; flex: 1; }
.post-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  font-size: .8rem;
  color: var(--text-dim);
  margin-bottom: 11px;
}
.tag {
  padding: 3px 10px;
  border-radius: 999px;
  background: rgba(79, 140, 255, .14);
  color: var(--brand);
  font-size: .74rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.post-body h3 { font-size: 1.14rem; margin-bottom: 9px; }
.post-body h3 a { color: #fff; }
.post-body h3 a:hover { color: var(--brand-2); }
.post-body p { color: var(--text-muted); font-size: .94rem; flex: 1; }

/* ---------- Article ---------- */
.article-header { padding: clamp(38px, 6vw, 74px) 0 clamp(22px, 3vw, 34px); }
.breadcrumb {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  list-style: none;
  padding: 0;
  margin: 0 0 20px;
  font-size: .87rem;
  color: var(--text-dim);
}
.breadcrumb a { color: var(--text-muted); }
.breadcrumb a:hover { color: var(--brand-2); }
.breadcrumb li + li::before { content: "/"; margin-right: 7px; color: var(--text-dim); }

.article-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: center;
  color: var(--text-dim);
  font-size: .9rem;
  margin-top: 18px;
}
.article-meta .avatar {
  width: 34px; height: 34px;
  border-radius: 50%;
  background: var(--accent-gradient);
  display: grid; place-items: center;
  color: #04070f;
  font-weight: 800;
  font-size: .85rem;
}

.prose { font-size: 1.06rem; line-height: 1.78; color: #cfd8ea; }
.prose h2 {
  margin-top: 2.3em;
  margin-bottom: .6em;
  font-size: clamp(1.4rem, 1.2rem + 1vw, 1.85rem);
  padding-top: .4em;
  border-top: 1px solid var(--border-soft);
}
.prose h3 { margin-top: 1.9em; margin-bottom: .5em; color: #fff; }
.prose h2:first-child { margin-top: 0; border-top: 0; padding-top: 0; }
.prose p { margin-bottom: 1.25em; }
.prose strong { color: #fff; }
.prose a {
  color: var(--brand);
  text-decoration: underline;
  text-underline-offset: 3px;
  text-decoration-color: rgba(79, 140, 255, .45);
}
.prose a:hover { text-decoration-color: var(--brand-2); }
.prose ul, .prose ol { margin-bottom: 1.4em; }
.prose li { margin-bottom: .55em; }
.prose blockquote {
  margin: 1.8em 0;
  padding: 16px 22px;
  border-left: 3px solid var(--brand);
  background: rgba(79, 140, 255, .07);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  color: var(--text);
  font-style: italic;
}
.prose img {
  border-radius: var(--radius);
  border: 1px solid var(--border);
  margin: 1.6em 0;
}
.prose figure { margin: 1.8em 0; }
.prose figcaption {
  text-align: center;
  font-size: .87rem;
  color: var(--text-dim);
  margin-top: 10px;
}

.prose table {
  width: 100%;
  border-collapse: collapse;
  margin: 1.8em 0;
  font-size: .95rem;
  display: block;
  overflow-x: auto;
}
.prose th, .prose td {
  border: 1px solid var(--border);
  padding: 12px 15px;
  text-align: left;
}
.prose th {
  background: var(--bg-elev-2);
  color: #fff;
  font-weight: 700;
}
.prose tbody tr:nth-child(even) { background: rgba(255, 255, 255, .022); }

.prose pre {
  background: #05080f;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 18px 20px;
  overflow-x: auto;
  line-height: 1.6;
  font-size: .89rem;
  margin: 1.6em 0;
}
.prose code {
  background: rgba(79, 140, 255, .13);
  color: #9ec3ff;
  padding: .16em .44em;
  border-radius: 5px;
  font-size: .87em;
}
.prose pre code { background: none; color: #cbd5e1; padding: 0; font-size: 1em; }

/* Table of contents */
.toc {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px 24px;
  margin: 0 0 34px;
}
.toc h2 {
  font-size: .82rem;
  text-transform: uppercase;
  letter-spacing: .12em;
  color: var(--brand-2);
  margin-bottom: 12px;
  border: 0;
  padding: 0;
}
.toc ol { margin: 0; padding-left: 1.2em; font-size: .94rem; }
.toc a { color: var(--text-muted); }
.toc a:hover { color: var(--brand-2); }

/* Callout boxes */
.callout {
  border-radius: var(--radius);
  padding: 18px 22px;
  margin: 1.8em 0;
  border: 1px solid;
  font-size: .98rem;
}
.callout p:last-child { margin-bottom: 0; }
.callout-title {
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 7px;
}
.callout-info { background: rgba(79,140,255,.08); border-color: rgba(79,140,255,.32); }
.callout-info .callout-title { color: var(--brand); }
.callout-warn { background: rgba(251,191,36,.08); border-color: rgba(251,191,36,.32); }
.callout-warn .callout-title { color: var(--warning); }
.callout-tip { background: rgba(52,211,153,.08); border-color: rgba(52,211,153,.32); }
.callout-tip .callout-title { color: var(--success); }

/* Verdict / review box */
.verdict {
  background: linear-gradient(150deg, rgba(79,140,255,.1), rgba(167,139,250,.06));
  border: 1px solid rgba(79, 140, 255, .32);
  border-radius: var(--radius-lg);
  padding: clamp(24px, 4vw, 36px);
  margin: 2.2em 0;
}
.verdict-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  flex-wrap: wrap;
  margin-bottom: 18px;
}
.verdict-score {
  font-size: 2.6rem;
  font-weight: 800;
  letter-spacing: -.04em;
  background: var(--accent-gradient);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  line-height: 1;
}
.verdict-score small { font-size: 1rem; color: var(--text-dim); -webkit-text-fill-color: var(--text-dim); }

/* Ad slots — reserved, lazy, never layout-shifting */
.ad-slot {
  display: block;
  min-height: 90px;
  margin: 2rem auto;
  max-width: 728px;
  border: 1px dashed var(--border);
  border-radius: var(--radius-sm);
  background: rgba(255, 255, 255, .015);
  overflow: hidden;
}
.ad-label {
  display: block;
  text-align: center;
  font-size: .68rem;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--text-dim);
  padding-top: 6px;
}

/* ---------- Author box ---------- */
.author-box {
  display: flex;
  gap: 18px;
  align-items: flex-start;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  margin: 2.4em 0;
}
.author-box .avatar {
  width: 62px; height: 62px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--accent-gradient);
  display: grid; place-items: center;
  color: #04070f;
  font-weight: 800;
  font-size: 1.3rem;
}
.author-box h3 { font-size: 1.05rem; margin-bottom: 4px; }
.author-box p { font-size: .93rem; color: var(--text-muted); margin-bottom: 0; }

/* ---------- Related ---------- */
.related { margin-top: 3rem; padding-top: 2.4rem; border-top: 1px solid var(--border); }

/* ---------- Forms ---------- */
.form { display: grid; gap: 18px; }
.field { display: grid; gap: 8px; }
.field label { font-size: .92rem; font-weight: 600; color: var(--text); }
.field input,
.field textarea,
.field select {
  width: 100%;
  padding: 13px 16px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text);
  font-family: inherit;
  font-size: .98rem;
  transition: border-color .18s ease, box-shadow .18s ease;
}
.field input:focus,
.field textarea:focus,
.field select:focus {
  outline: none;
  border-color: var(--brand);
  box-shadow: 0 0 0 3px rgba(79, 140, 255, .18);
}
.field textarea { min-height: 150px; resize: vertical; }
.field .hint { font-size: .82rem; color: var(--text-dim); }

.form-note {
  font-size: .87rem;
  color: var(--text-dim);
  padding: 14px 16px;
  background: rgba(255, 255, 255, .03);
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
}

/* ---------- Newsletter ---------- */
.newsletter {
  display: flex;
  gap: 12px;
  max-width: 520px;
  flex-wrap: wrap;
}
.newsletter input {
  flex: 1;
  min-width: 220px;
  padding: 13px 17px;
  background: rgba(0, 0, 0, .3);
  border: 1px solid var(--border);
  border-radius: 999px;
  color: var(--text);
  font-size: .97rem;
}
.newsletter input:focus {
  outline: none;
  border-color: var(--brand);
  box-shadow: 0 0 0 3px rgba(79, 140, 255, .18);
}

/* ---------- Page header (inner pages) ---------- */
.page-head {
  padding: clamp(40px, 6vw, 78px) 0 clamp(24px, 4vw, 42px);
  border-bottom: 1px solid var(--border-soft);
}
.page-head p { max-width: 680px; color: var(--text-muted); font-size: 1.08rem; }

/* ---------- Pagination ---------- */
.pagination {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 3rem;
  list-style: none;
  padding: 0;
}
.pagination a, .pagination span {
  display: grid;
  place-items: center;
  min-width: 42px;
  height: 42px;
  padding: 0 14px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--bg-elev);
  color: var(--text-muted);
  font-weight: 600;
  font-size: .93rem;
}
.pagination a:hover { border-color: var(--brand); color: #fff; }
.pagination .current {
  background: var(--accent-gradient);
  color: #04070f;
  border-color: transparent;
}

/* ---------- Footer ---------- */
.site-footer {
  margin-top: clamp(48px, 7vw, 90px);
  border-top: 1px solid var(--border-soft);
  background: linear-gradient(180deg, rgba(255,255,255,.015), transparent);
  padding: clamp(38px, 5vw, 62px) 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr;
  gap: clamp(26px, 4vw, 54px);
  padding-bottom: 32px;
  border-bottom: 1px solid var(--border-soft);
}
.footer-brand p {
  color: var(--text-muted);
  font-size: .94rem;
  margin-top: 14px;
  max-width: 400px;
}
.footer-col h2 {
  font-size: .78rem;
  text-transform: uppercase;
  letter-spacing: .13em;
  color: var(--text-dim);
  margin-bottom: 15px;
  font-weight: 700;
}
.footer-col ul { list-style: none; padding: 0; margin: 0; }
.footer-col li { margin-bottom: 9px; }
.footer-col a { color: var(--text-muted); font-size: .94rem; }
.footer-col a:hover { color: var(--brand-2); }

.footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  padding-top: 24px;
}
.footer-bottom p { margin: 0; font-size: .88rem; color: var(--text-dim); }

/* ---------- Utilities ---------- */
.text-center { text-align: center; }
.mt-0 { margin-top: 0; }
.mb-0 { margin-bottom: 0; }
.mt-2 { margin-top: 1.4rem; }
.mt-3 { margin-top: 2.2rem; }
.sr-only {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

/* ---------- Reveal on scroll ---------- */
.reveal {
  opacity: 0;
  transform: translateY(22px);
  transition: opacity .6s cubic-bezier(.2,.7,.3,1), transform .6s cubic-bezier(.2,.7,.3,1);
}
.reveal.is-visible { opacity: 1; transform: none; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .001ms !important;
    transition-duration: .001ms !important;
    scroll-behavior: auto !important;
  }
  .reveal { opacity: 1; transform: none; }
}

/* ---------- Responsive ---------- */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .hero-grid { grid-template-columns: 1fr; }
  .hero-card { order: 2; }
}

@media (max-width: 880px) {
  body { font-size: 16px; }

  .nav-toggle { display: flex; }

  .primary-nav {
    position: fixed;
    inset: var(--header-h) 0 auto 0;
    background: rgba(7, 11, 20, .98);
    backdrop-filter: blur(16px);
    border-bottom: 1px solid var(--border);
    padding: 14px 22px 22px;
    transform: translateY(-130%);
    opacity: 0;
    visibility: hidden;
    transition: transform .28s ease, opacity .24s ease, visibility .24s;
    margin-left: 0;
    max-height: calc(100vh - var(--header-h));
    overflow-y: auto;
  }
  .primary-nav.open {
    transform: translateY(0);
    opacity: 1;
    visibility: visible;
  }
  .primary-nav ul { flex-direction: column; align-items: stretch; gap: 4px; }
  .primary-nav a { padding: 13px 16px; font-size: 1.02rem; }

  .header-actions .btn { display: none; }

  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 30px; }
  .footer-bottom { flex-direction: column; gap: 8px; }
  .author-box { flex-direction: column; }
}

@media (max-width: 560px) {
  .container { padding-inline: 18px; }
  .hero-stats { gap: 20px; }
  .hero-stats .stat { flex: 1 1 40%; }
  .btn-group .btn { width: 100%; }
  .prose table { font-size: .87rem; }
}

/* ---------- Print ---------- */
@media print {
  .site-header, .site-footer, .ad-slot, .cta-band, .nav-toggle { display: none !important; }
  body { background: #fff; color: #000; }
}

/* ---- Blogger-specific adjustments ---- */
.widget { margin: 0; }
.ad-zone { margin: 0 auto; max-width: 1180px; padding: 12px 20px; text-align: center; }
.ad-zone:not(:empty) { padding-top: 22px; padding-bottom: 6px; }
h1.post-title { margin-top: 14px; }
main#main { min-height: 50vh; }
.post-card .card-link { margin-top: 14px; }
.section-tight#latest { padding-top: 4px; }
.article-header .breadcrumb { margin-bottom: 8px; }
.post-card .post-body { justify-content: flex-start; }

