body.script:
  //
/* AI Tool Scout — progressive enhancement only.
   Everything works without JS; this adds polish. */
(function () {
  "use strict";

  /* ---------- Sticky header shadow ---------- */
  var header = document.getElementById("site-header");
  if (header) {
    var onScroll = function () {
      header.classList.toggle("scrolled", window.scrollY > 8);
    };
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
  }

  /* ---------- Mobile navigation ---------- */
  var toggle = document.getElementById("nav-toggle");
  var nav = document.getElementById("primary-nav");
  if (toggle && nav) {
    toggle.addEventListener("click", function () {
      var open = toggle.getAttribute("aria-expanded") === "true";
      toggle.setAttribute("aria-expanded", String(!open));
      nav.classList.toggle("open", !open);
    });

    nav.addEventListener("click", function (e) {
      if (e.target.closest("a")) {
        toggle.setAttribute("aria-expanded", "false");
        nav.classList.remove("open");
      }
    });

    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape") {
        toggle.setAttribute("aria-expanded", "false");
        nav.classList.remove("open");
      }
    });
  }

  /* ---------- Reveal on scroll (respects reduced motion) ---------- */
  var reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var targets = document.querySelectorAll(".reveal");

  if (!reduceMotion && "IntersectionObserver" in window && targets.length) {
    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-visible");
            io.unobserve(entry.target);
          }
        });
      },
      { rootMargin: "0px 0px -8% 0px", threshold: 0.06 }
    );
    targets.forEach(function (el) { io.observe(el); });
  } else {
    targets.forEach(function (el) { el.classList.add("is-visible"); });
  }

  /* ---------- Table of contents is generated at build time.
     This block only assigns ids to any h2 added dynamically. ---------- */
  var article = document.querySelector("[data-toc-source]");
  if (article) {
    article.querySelectorAll("h2").forEach(function (h, i) {
      if (!h.id) h.id = "section-" + (i + 1);
    });
  }

  /* ---------- Copy buttons on code blocks ---------- */
  document.querySelectorAll(".prose pre").forEach(function (pre) {
    var btn = document.createElement("button");
    btn.type = "button";
    btn.className = "btn btn-ghost btn-sm";
    btn.textContent = "Copy";
    btn.style.position = "absolute";
    btn.style.right = "10px";
    btn.style.top = "10px";
    pre.style.position = "relative";
    pre.appendChild(btn);
    btn.addEventListener("click", function () {
      var code = pre.querySelector("code");
      var text = code ? code.innerText : pre.innerText;
      if (navigator.clipboard) {
        navigator.clipboard.writeText(text).then(function () {
          btn.textContent = "Copied!";
          setTimeout(function () { btn.textContent = "Copy"; }, 1600);
        });
      }
    });
  });

  /* ---------- Newsletter / contact forms (no backend: mailto fallback) ---------- */
  document.querySelectorAll("[data-demo-form]").forEach(function (form) {
    form.addEventListener("submit", function (e) {
      e.preventDefault();
      var note = form.querySelector("[data-form-note]");
      if (note) {
        note.hidden = false;
        note.textContent =
          "Thanks! This demo form is not connected to a backend yet — please email us directly.";
      }
    });
  });
})();

  //

//
(function(){
  var KEY = 'aits_cookie_consent';
  var bar = document.getElementById('aits-cookie-bar');
  if (!bar) return;
  function read(){ try { return localStorage.getItem(KEY); } catch (e) { return null; } }
  function write(v){ try { localStorage.setItem(KEY, v); } catch (e) {} }
  function show(){ bar.hidden = false; }
  function hide(){ bar.hidden = true; }
  if (!read()) show();
  var acc = document.getElementById('aits-cookie-accept');
  var dec = document.getElementById('aits-cookie-decline');
  if (acc) acc.addEventListener('click', function(){ write('granted'); window.__gtagConsent && window.__gtagConsent('granted'); hide(); });
  if (dec) dec.addEventListener('click', function(){ write('denied');  window.__gtagConsent && window.__gtagConsent('denied');  hide(); });
  document.addEventListener('click', function(e){
    var t = e.target;
    if (t && t.closest && t.closest('#aits-cookie-settings')) { e.preventDefault(); show(); }
  });
})();
//
